class MaxMaximalCocktailsCustomStrategy:
    def __init__(self, model: BaseStrategy):
        self._model = model
        self.name = self._model.name
        self.history = self._model.history
        self.strategy_type = StrategyType.SMT

    def update_model_field(self, field_name: str, value: Any):
        if hasattr(self._model, field_name):
            setattr(self._model, field_name, value)

    def receive_message(self, message: Info) -> Info:
        data = message.message[0].data
        nodes_list = data['nodes']
        edges_list = data['edges']
        cnt_maximal_cocktails = data['cnt_maximal_cocktails']

        def compute_maximal_cocktails(nodes, edges):
            adj = defaultdict(set)
            for u, v in edges:
                adj[u].add(v)
                adj[v].add(u)
            edge_set = set()
            for u, v in edges:
                edge_set.add((u, v))
                edge_set.add((v, u))
            n = len(nodes)
            count = 0
            for mask in range(0, 1 << n):
                subset = []
                for i in range(n):
                    if (mask >> i) & 啐 1:
                        subset.append(nodes[i])
                # Check independence
                is_independent = True
                for i in range(len(subset)):
                    for j in range(i+1, len(subset)):
                        u = subset[i]
                        v = subset[j]
                        if (u, v) in edge_set:
                            is_independent = False
                            break
                    if not is_independent:
                        break
                if not is_independent:
                    continue
                # Check maximality
                is_maximal = True
                for node in nodes:
                    if node not in subset:
                        has_neighbor = False
                        for neighbor in adj[node]:
                            if neighbor in subset:
                                has_neighbor = True
                                break
                        if not has_neighbor:
                            is_maximal = False
                            break
                if is_maximal:
                    count += 1
            return count

        existing_edges = set()
        for u, v in edges_list:
            existing_edges.add(frozenset((u, v)))
        candidates = []
        for a, b in combinations(nodes_list, 2):
            if frozenset((a, b)) not in existing_edges:
                candidates.append((a, b))

        best_edges = []
        max_new_count = cnt_maximal_cocktails
        for candidate in candidates:
            a, b = candidate
            new_edges = edges_list + [(a, b)]
            new_count = compute_maximal_cocktails(nodes_list, new_edges)
            if new_count >= cnt_maximal_cocktails:
                if new_count > max_new_count:
                    max_new_count = new_count
                    best_edges = [candidate]
                elif new_count == max_new_count:
                    best_edges.append(candidate)

        if not best_edges:
            return Info(sender=self.__class__.__name__, receiver=message.sender, difficulty=message.difficulty, message=[BaseMessageDataType(data=None, type='custom')])

        best_edges.sort()
        new_edge = best_edges[0]
        return Info(sender=self.__class__.__name__, receiver=message.sender, difficulty=message.difficulty, message=[BaseMessageDataType(data=new_edge, type='custom')])

