    def __init__(self, model: BaseStrategy):
        self._model = model
        self.name = self._model.name
        self.history = self._model.history
        self.strategy_type = StrategyType.SMT

    def update_model_field(self, field_name: str, value: Any):
        if hasattr(self._model, field_name):
            setattr(self._model, field_name, value)

    def receive_message(self, message: Info) -> Info:
        data = message.message[0].data
        nodes_list = data['nodes']
        edges_list = data['edges']
        cnt_maximal_cocktails = data['cnt_maximal_cocktails']

        def count_maximal_independent_sets(nodes, edges):
            adj = {node: [] for node in nodes}
            for u, v in edges:
                adj[u].append(v)
                adj[v].append(u)
            sorted_nodes = sorted(nodes)
            n = len(sorted_nodes)
            count = 0
            for mask in range(0, 1 << n):
                subset = []
                for i in range(n):
                    if (mask >> i) & 1:
                        subset.append(sorted_nodes[i])
                # Check independent
                is_independent = True
                for i in range(len(subset)):
                    for j in range(i+1, len(subset)):
                        a, b = subset[i], subset[j]
                        if a in adj[b]:
                            is_independent = False
                            break
                    if not is_independent:
                        break
                if not is_independent:
                    continue
                # Check maximal
                is_maximal = True
                for node in sorted_nodes:
                    if node not in subset:
                        adjacent = False
                        for neighbor in adj[node]:
                            if neighbor in subset:
                                adjacent = True
                                break
                        if not adjacent:
                            is_maximal = False
                            break
                if is_maximal:
                    count += 1
            return count

        current_edges_set = set()
        for u, v in edges_list:
            current_edges_set.add(frozenset({u, v}))
        candidates = []
        nodes_sorted = sorted(nodes_list)
        for i in range(len(nodes_sorted)):
            u = nodes_sorted[i]
            for j in range(i+1, len(nodes_sorted)):
                v = nodes_sorted[j]
                edge = frozenset({u, v})
                if edge not in current_edges_set:
                    candidates.append((u, v))

        valid_candidates = []
        max_new_count = -1
        for candidate in candidates:
            u, v = candidate
            new_edges = edges_list + [(u, v)]
            new_count = count_maximal_independent_sets(nodes_list, new_edges)
            if new_count >= cnt_maximal_cocktails:
                valid_candidates.append((candidate, new_count))
                if new_count > max_new_count:
                    max_new_count = new_count

        best_candidates = []
        if valid_candidates:
            for cand, cnt in valid_candidates:
                if cnt == max_new_count:
                    best_candidates.append(cand)
            new_edge = best_candidates[0]
        else:
            if candidates:
                new_edge = candidates[0]
            else:
                new_edge = (nodes_list[0], nodes_list[1])

        return Info(
            sender=self.__class__.__name__,
            receiver=message.sender,
            difficulty=message.difficulty,
            message=[BaseMessageDataType(data=new_edge, type='custom')]
        )

